def build_agent(sandbox):
    # Use documented primitive to create sled (pre-initialized)
    return sandbox.add_sled(x=8.0, y=2.0, width=1.0, height=0.5, density=1.0)

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_sled_position()
    if pos is None:
        return
    x, y = pos
    vel = sandbox.get_sled_velocity() or (0.0, 0.0)
    vx, vy = vel[0], vel[1]
    speed = math.sqrt(vx * vx + vy * vy)

    # Check if checkpoints are passed
    past_a = sandbox.get_checkpoint_a_reached()
    past_b = sandbox.get_checkpoint_b_reached()

    # Define critical zones
    in_drain = 11.0 <= x <= 17.0
    in_reverse = 20.0 <= x <= 25.0
    in_thrust_scale = 19.5 <= x <= 21.0
    in_oscillating_fx = 21.0 <= x <= 27.0
    in_speed_penalty = 22.0 <= x <= 26.0
    in_vert_reverse = 26.5 <= x <= 28.5

    # Adjusted parameters for new environment
    K_X = 10.0  # Reduced for better momentum retention
    K_X_DRAIN = 25.0  # Slightly reduced to prevent over-acceleration
    K_Y = 100.0
    K_Y_CHECKPOINT = 120.0
    K_BRAKE = 40.0  # Reduced braking force in terminal region
    MAX_THRUST = 500.0
    THRUST_SCALE_FACTOR = 0.5  # Preserves momentum in non-critical zones

    # Calculate forces
    fx = 0.0
    fy = 0.0

    if not past_a:
        dy = (17.5 + 19.0)/2 - y
        fy = 260.0 + K_Y_CHECKPOINT * dy
    elif past_b:
        if in_vert_reverse:
            fy = -(260.0 + K_Y * (2.2 + 2.8)/2 - y)
        else:
            fy = 260.0 + K_Y * ((2.2 + 2.8)/2 - y)
    else:
        dy = (23.0 + 24.5)/2 - y
        fy = 260.0 + K_Y * dy * 1.4

    # Wind compensation
    if 14.0 <= x <= 28.0:
        fy -= 20.0 + 20.0 * math.sin(step_count * 0.06)

    # Braking logic
    if x > 28.0:
        if in_reverse:
            fx = K_BRAKE * vx if vx > 0 else K_BRAKE * 2.0
        else:
            fx = -K_BRAKE * vx if vx > 0 else -K_BRAKE * 2.0
        if not in_reverse and fx > 0:
            fx = 0
        if in_reverse and fx < 0:
            fx = 0
    elif x >= 28.0:
        if in_reverse:
            fx = K_BRAKE * vx
        else:
            fx = -K_BRAKE * vx
    elif x > 25.0:
        fx = K_X * ((23.0 + 24.5)/2 - x)
    elif past_b and x <= 25.0:
        fx = -K_X * ((23.0 + 24.5)/2 - x)
    elif past_b:
        fx = K_X * ((23.0 + 24.5)/2 - x)
    elif past_a and x < 20.0:
        fx = K_X * ((23.0 + 24.5)/2 - x)
        if in_drain:
            fx *= (K_X_DRAIN / K_X)
    elif past_a:
        dx_b = ((23.0 + 24.5)/2 - x)
        fx = -K_X * dx_b
        if in_drain:
            fx *= (K_X_DRAIN / K_X)
        if in_speed_penalty and speed > 4.0 * 0.8:
            fx *= 0.4
        if 23.0 <= x <= 24.5:
            if y > 3.2:
                fx *= 0.45
            else:
                fx *= 0.7
        elif 21.0 <= x < 23.0:
            fx *= 0.85
    else:
        dx = (17.5 + 19.0)/2 - x
        fx = K_X * dx
        if in_drain:
            fx *= (K_X_DRAIN / K_X)
        if 15.0 <= x < 17.5 and dx > 0:
            fx *= 1.4

    # Oscillating force compensation
    if in_oscillating_fx:
        fx -= 30.0 * math.sin(step_count * 0.04)

    # Thrust scaling
    if in_thrust_scale:
        fx *= (1.0 / THRUST_SCALE_FACTOR)
        fy *= (1.0 / THRUST_SCALE_FACTOR)

    # Normalize thrust
    f = math.sqrt(fx * fx + fy * fy)
    if f > MAX_THRUST:
        scale = MAX_THRUST / f
        fx *= scale
        fy *= scale

    sandbox.apply_thrust(fx, fy)
